package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueStatusOptions;

class StatusVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property status of observed issue ")
  void test_status_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> StatusVO.tryFrom("_UNRESOLVED_"));
    Assertions.assertEquals(ObservedIssueStatusOptions.UNRESOLVED,
        StatusVO.tryFrom("UNRESOLVED").getStatus());
    Assertions.assertThrows(ConstraintException.class, () -> StatusVO.tryFrom(null));
    Assertions.assertEquals(ObservedIssueStatusOptions.UNRESOLVED,
        StatusVO.from(ObservedIssueStatusOptions.UNRESOLVED).getStatus());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> StatusVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedIssueStatusOptions.UNRESOLVED + "]",
        StatusVO.from(ObservedIssueStatusOptions.UNRESOLVED).toString());
  }
}
